using System.Collections;
using System.IO;
using UnityEditor;
using UnityEngine;
[InitializeOnLoad] public static class StorybookLevelUpValidation{
 const string Out="output/level-up/";static bool running;static double started;
 static StorybookLevelUpValidation(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool("LEVEL_UI_QA",false)){SessionState.SetBool("LEVEL_UI_QA",false);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",false);running=false;}};}
 static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||StorybookLevelUpAuthoring.Busy)return;if(!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(Out+"validate.request")){File.Delete(Out+"validate.request");File.WriteAllText(Out+"validation.txt","");SessionState.SetBool("LEVEL_UI_QA",true);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",true);EditorApplication.isPlaying=true;}if(EditorApplication.isPlaying&&SessionState.GetBool("LEVEL_UI_QA",false)&&!running&&GameManager.single&&GameplayCanvas.single){running=true;started=EditorApplication.timeSinceStartup;GameManager.single.StartCoroutine(Run());}if(running&&EditorApplication.timeSinceStartup-started>180){Check(false,"Timeout");EditorApplication.isPlaying=false;}}
 static void Check(bool ok,string s)=>File.AppendAllText(Out+"validation.txt",(ok?"PASS ":"FAIL ")+s+"\n");
 static void Shot(string name){var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Out+name+".png",t.EncodeToPNG());Object.Destroy(t);}
 static IEnumerator Run(){var intro=Object.FindAnyObjectByType<CursedBookIntro>(FindObjectsInactive.Include);while(intro&&intro.gameObject.activeSelf)yield return null;yield return new WaitForSecondsRealtime(1);var gc=GameplayCanvas.single;var gm=GameManager.single;TutorialManager.single.automatic=false;TutorialManager.single.view.Hide();for(int i=0;i<9;i++)if(!gm.HasSeenThis("Tutorial-"+i))gm.thingsSeenPermanent.Add("Tutorial-"+i);gc.CancelInvoke("TryShowingXpBoosterNotification");gc.xpBoosterNotification.SetActive(false);gc.dailyCherriesPop.SetActive(false);var ui=gc.levelUpUI;Check(ui,"Scene references new prefab");if(!ui){EditorApplication.isPlaying=false;yield break;}
 foreach(var size in new[]{new Vector2Int(1080,1920),new Vector2Int(768,1024),new Vector2Int(720,1440)}){StorybookEquipmentValidation.Resolution(size.x,size.y);yield return new WaitForSecondsRealtime(.3f);gm.playerLevel=5;int stat=gm.statPoints,skill=gm.skillPoints;gc.PlayLevelUp();yield return new WaitForSecondsRealtime(.6f);Check(ui.Presenting&&ui.group.alpha>.99f,"Visible level banner "+size);Check(ui.AttributePoints==1&&ui.SkillPoints==1,"Level five reward labels "+size);Check(gm.statPoints==stat&&gm.skillPoints==skill,"Presentation never grants rewards "+size);Check(!ui.group.blocksRaycasts,"Input passes through "+size);var corners=new Vector3[4];ui.card.GetWorldCorners(corners);Check(corners[0].x>=0&&corners[2].x<=Screen.width+1&&corners[0].y>=0&&corners[2].y<=Screen.height+1,"Within viewport "+size);yield return new WaitForEndOfFrame();Shot("level-five-"+size.x+"x"+size.y);yield return new WaitForSecondsRealtime(2.2f);Check(!ui.Presenting,"Auto dismissal "+size);}
 StorybookEquipmentValidation.Resolution(1080,1920);int before=gm.statPoints;gm.playerLevel=8;gm.SendMessage("LevelUpEvent");gm.SendMessage("LevelUpEvent");gm.SendMessage("LevelUpEvent");yield return new WaitForSecondsRealtime(.5f);Check(ui.FromLevel==8&&ui.ToLevel==11&&ui.AttributePoints==3&&ui.SkillPoints==1,"Actual consecutive upgrades aggregate correctly");Check(gm.statPoints==before+3,"Original progression still grants exactly three points");yield return new WaitForEndOfFrame();Shot("consecutive-levels");gc.ShowItemPopUp(new Item{itemGrade=ItemGrade.UI_ONLY,m_ItemFinalTitle="属性点 +1"});yield return new WaitForSecondsRealtime(.5f);Check(gc.itemToast.Presenting&&gc.itemToast.group.alpha==0,"Item notification waits behind level banner");yield return new WaitForSecondsRealtime(1.9f);Check(!ui.Presenting&&gc.itemToast.group.alpha>.9f,"Item resumes after level presentation");yield return new WaitForSecondsRealtime(3);
 Router.single.LastBattle();yield return new WaitForSecondsRealtime(3);gm.SendMessage("LevelUpEvent");yield return new WaitForSecondsRealtime(.6f);yield return new WaitForEndOfFrame();Shot("battle-level-up");Check(ui.Presenting&&!ui.group.blocksRaycasts,"Actual battle upgrade presents without blocking");Check(gc.battleHud.levelText.text=="Lv. "+gm.playerLevel,"Battle HUD level matches upgrade immediately");File.AppendAllText(Out+"validation.txt","DONE\n");EditorApplication.isPlaying=false;}
}
